// spec: specs/data-requests-reauth.md (2.1–2.3) · кейсы DR-01, DR-02, DR-06 на iPhone · запасной путь (MCP playwright-test отключён)
// seed: tests/seed.parent-b.spec.ts
// Устройство задано здесь: iPhone WebKit 390×844 (как при проверке 02.11); проект iphone по умолчанию 375.
// Пароль не вводится, запрос не отправляется (записи обрываются в браузере), письмо не отправляется.
import { test, expect, devices } from '@playwright/test';
import {
  PARENT_B,
  T,
  blockDataRequestWrites,
  cancelReauth,
  chip,
  expectReauthDialog,
  openForm,
  sendButton,
  visibleText,
} from './data-requests.helpers';
import { expectSupportContact } from './support.helpers';

test.use({
  browserName: 'webkit',
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 3,
  userAgent: devices['iPhone 13'].userAgent,
  storageState: PARENT_B,
});

test.describe('Запросы данных — iPhone 390', () => {
  test('iPhone 390: удаление данных ребёнка → «אימות זהות», без POST; «ביטול» @iphone @prod-safe #c3aa39', async ({ page }) => {
    const writes = await blockDataRequestWrites(page);
    await openForm(page);
    await chip(page, 'QA-B1').click();
    await chip(page, T.kindDelete).click();
    await expect(page.getByText(T.deleteChildHint).filter({ visible: true }).first()).toBeVisible();

    await sendButton(page).click();
    await expectReauthDialog(page);
    expect(writes, `до пароля не было записи запроса: ${JSON.stringify(writes)}`).toEqual([]);

    await cancelReauth(page);
    await expect(visibleText(page, T.formTitle)).toBeVisible();
    await expect(page.getByText(T.deleteChildHint).filter({ visible: true }).first()).toBeVisible();
    expect(writes).toEqual([]);
  });

  test('iPhone 390: удаление всей семьи из /settings → «אימות זהות», без POST; «ביטול» @iphone @prod-safe #c3aa39', async ({ page }) => {
    const writes = await blockDataRequestWrites(page);
    await page.goto('/settings');
    await visibleText(page, T.settingsFamilyLink).click();
    await expect(page).toHaveURL(/\/privacy\/data-request/);
    await expect(page.getByText(T.deleteFamilyHint).filter({ visible: true }).first()).toBeVisible();

    await sendButton(page).click();
    await expectReauthDialog(page);
    expect(writes, `до пароля не было записи запроса: ${JSON.stringify(writes)}`).toEqual([]);

    await cancelReauth(page);
    await expect(page.getByText(T.deleteFamilyHint).filter({ visible: true }).first()).toBeVisible();
    expect(writes).toEqual([]);
  });

  test('iPhone 390: контакт поддержки (mailto) на /privacy, /settings, /consent?doc=terms @iphone @prod-safe #c3aa39', async ({ page }) => {
    for (const url of ['/privacy', '/settings', '/consent?doc=terms']) {
      await page.goto(url);
      await expectSupportContact(page);
    }
  });
});
